"/></el-form-item></el-col><el-col :span="6"><el-form-item label="填报人"><el-input value="安环管理员" disabled/></el-form-item></el-col></el-row><div class="form-block-title"><span>伤者基本信息</span><em>选择伤者后自动带出</em></div><el-row :gutter="20"><el-col :span="6"><el-form-item label="伤者姓名"><el-input v-model="injury.name" disabled><el-button slot="append" icon="el-icon-user" @click="editInjury(injury)"></el-button></el-input></el-form-item></el-col><el-col :span="6"><el-form-item label="身份证号"><el-input v-model="injury.idCard"/></el-form-item></el-col><el-col :span="6"><el-form-item label="电话"><el-input v-model="injury.phone"/></el-form-item></el-col><el-col :span="6"><el-form-item label="入职日期"><el-input v-model="injury.entryDate"/></el-form-item></el-col><el-col :span="12"><el-form-item label="家庭地址"><el-input v-model="injury.address"/></el-form-item></el-col><el-col :span="6"><el-form-item label="伤者岗位"><el-input v-model="injury.position"/></el-form-item></el-col><el-col :span="6"><el-form-item label="直接领导"><el-input v-model="injury.leader"/></el-form-item></el-col><el-col :span="6"><el-form-item label="直接领导电话"><el-input v-model="injury.leaderPhone"/></el-form-item></el-col></el-row><div class="form-block-title"><span>事故与伤情说明</span><em>与事故概况关联，可继续补充</em></div><el-row :gutter="20"><el-col :span="6"><el-form-item label="受伤时间"><el-input v-model="injury.injuredAt"/></el-form-item></el-col><el-col :span="6"><el-form-item label="事发地点"><el-input :value="accident.location" disabled/></el-form-item></el-col><el-col :span="6"><el-form-item label="诊断结果"><el-input v-model="injury.diagnosis" placeholder="请输入诊断结果"/></el-form-item></el-col><el-col :span="12"><el-form-item label="目前伤者情况"><el-input v-model="injury.currentCondition"/></el-form-item></el-col><el-col :span="24"><el-form-item label="受伤害简要经过"><el-input v-model="injury.brief" type="textarea" :rows="4"/></el-form-item></el-col></el-row><div class="form-block-title witness-title"><span>证明人</span><el-button type="text" size="mini" icon="el-icon-plus" @click="addWitness(injury)">新增证明人</el-button></div><div v-for="(witness, witnessIndex) in injury.witness" :key="witnessIndex" class="witness-row"><span class="witness-label">证明人{{ witnessIndex + 1 }}</span><el-input v-model="witness.name" placeholder="姓名"/><el-input v-model="witness.phone" placeholder="电话"/><el-input v-model="witness.position" placeholder="岗位"/><el-button v-if="injury.witness.length > 1" type="text" class="danger-text" @click="injury.witness.splice(witnessIndex, 1)">删除</el-button></div><div class="form-block-title"><span>目前防范措施</span><em>可根据事故实际情况补充</em></div><el-form-item label=""><el-input v-model="injury.prevention" type="textarea" :rows="4" placeholder="请填写事故后的防范措施"/></el-form-item><div class="form-footer"><span class="save-hint"><i class="el-icon-info"></i> 申请表内容仅保存于本地 Mock 数据</span><el-button size="small" type="primary" @click="saveInjury(injury)">保存本张申请表</el-button></div></el-form></div></transition></div></div></section>

