<script>
import { accidents, employeeOptions } from '../mock/accidents';
import '../mixins/accidentWorkflow';
export default { name: 'AccidentDetail', props: { id: { type: String, default: '' } }, data () { return { accidents, employeeOptions, accident: null, overviewEditing: false, injuryDialogVisible: false, selectedEmployee: '', editingInjury: null, workshops: ['电池回收车间', '浸出净化车间', '维修动力车间', '成品车间'],  }; }, computed: { canStartApproval () { return this.accident && this.accident.workflowStatus === '未发起' && this.accident.injuries.length > 0 && this.accident.injuries.every(item => item.formStatus === '已填写'); }, workflowActive () { if (!this.accident || this.accident.workflowStatus === '未发起') return 0; if (this.accident.workflowStatus === '已结束') return 5; if (this.accident.currentNode === '安全环保部审批') return 1; if (this.accident.currentNode === '人力资源部审批') return 2; return 3; } }, created () { this.accident = this.accidents.find(item => item.id === this.id) || this.accidents[0]; this.accident.injuries.forEach(item => { if (!item.applyDate) this.$set(item, 'applyDate', '2026-05-12'); }); }, methods: { saveAll () { this.$message.success('事故概况及申请表已保存'); }, startApproval () { if (!this.canStartApproval) return this.$message.warning('请先完成事故下全部工伤认定申请表'); this.accident.workflowStatus = '审批中'; this.accident.currentNode = '安全环保部审批'; this.accident.ccStatus = '待抄送'; this.accident.hrStatus = '待审批'; this.$message.success('已发起事故级工伤认定申请审批'); }, mockAnhuanPass () { this.accident.currentNode = '人力资源部审批'; this.accident.ccStatus = '已抄送'; this.accident.hrStatus = '审批中'; this.$message.success('安全环保部已审批通过，已并行抄送主管部门'); }, mockHrPass () { this.accident.currentNode = '工伤保险办理人员签收'; this.accident.hrStatus = '已通过'; this.accident.insuranceHandler = '王丽'; this.$message.success('人力资源部部长已审批通过'); }, mockInsuranceSign () { this.accident.workflowStatus = '已结束'; this.accident.currentNode = '已结束'; this.accident.ccStatus = '已抄送'; this.accident.hrStatus = '已通过'; this.accident.insuranceHandler = '王丽（已签收）'; this.$message.success('工伤保险办理人员已签收，流程结束'); }, openInjuryDialog () { this.selectedEmployee = ''; this.editingInjury = null; this.injuryDialogVisible = true; }, editInjury (injury) { this.editingInjury = injury; this.selectedEmployee = injury.name; this.injuryDialogVisible = true; }, addInjury () { const employee = this.employeeOptions.find(item => item.name === this.selectedEmployee); if (!employee) return this.$message.warning('请选择伤者'); if (this.editingInjury) { Object.keys(employee).forEach(key => this.$set(this.editingInjury, key, employee[key])); this.$set(this.editingInjury, 'formStatus', '未填写'); this.$set(this.editingInjury, 'expanded', true); this.$message.success('伤者信息已更新'); } else { const injury = { ...employee, id: 'INJ-' + Date.now(), expanded: true, formStatus: '未填写', applyDate: '2026-07-22', injuredAt: this.accident.happenedAt, diagnosis: '', hospital: '', injuryPart: '', currentCondition: '', brief: this.accident.incident, prevention: '', witness: [{ name: '', phone: '', position: '' }], attachments: [] }; this.accident.injuries.push(injury); this.accident.injuredCount = this.accident.injuries.length; this.$message.success('已新增伤者申请表'); } this.injuryDialogVisible = false; }, removeInjury (index) { this.$confirm('确定删除这名伤者及其申请表吗？', '提示', { type: 'warning' }).then(() => { this.accident.injuries.splice(index, 1); this.accident.injuredCount = this.accident.injuries.length; this.accident.applicationCount = this.accident.injuries.filter(item => item.formStatus === '已填写').length; this.$message.success('已删除'); }).catch(() => {}); }, addWitness (injury) { injury.witness.push({ name: '', phone: '', position: '' }); }, saveInjury (injury) { injury.formStatus = injury.name && injury.diagnosis && injury.brief ? '已填写' : '未填写'; this.accident.applicationCount = this.accident.injuries.filter(item => item.formStatus === '已填写').length; this.accident.status = this.accident.injuries.length && this.accident.applicationCount === this.accident.injuries.length ? '已填写' : '未填写'; this.$message.success('本张工伤认定申请表已保存'); }, removeFile (injury, file) { const index = injury.attachments.findIndex(item => item.name === file.name); if (index > -1) injury.attachments.splice(index, 1); }, mockUpload (options) { setTimeout(() => { const file = { name: options.file.name, size: (options.file.size / 1024 / 1024).toFixed(1) + ' MB', status: 'success', uid: Date.now() }; const injury = this.accident.injuries.find(item => item.expanded); if (injury) injury.attachments.push(file); options.onSuccess(file); this.$message.success('文件已上传（Mock）'); }, 500); }, exportInjury (injury) { const content = ['中冶瑞木新能源科技有限公司 工伤认定申请表', '', '事故名称：' + this.accident.name, '伤者姓名：' + injury.name, '身份证号：' + injury.idCard, '受伤时间：' + injury.injuredAt, '事发地点：' + this.accident.location, '诊断结果：' + injury.diagnosis, '受伤害简要经过：' + injury.brief, '目前防范措施：' + injury.prevention, '目前伤者情况：' + injury.currentCondition].join('\n'); const blob = new Blob([content], { type: 'text/plain;charset=utf-8' }); const url = URL.createObjectURL(blob); const anchor = document.createElement('a'); anchor.href = url; anchor.download = (injury.name || '伤者') + '-工伤认定申请表.txt'; anchor.click(); URL.revokeObjectURL(url); this.$message.success('申请表已导出'); } } };
</script>

